INSERT INTO offers (config_id, product_id, tier_id, offer_name, buyer_trigger, outcome, modules_raw, deliverables, typical_format, commercial_model, reusable_core, specific_core, entry_criteria, exit_acceptance, explicit_exclusions, evidence_contract) VALUES ('DC-O3', 2, 3, 'Verifiable Execution PoC', 'The architecture needs measured proof on one workload', 'Run one representative workload and produce independently inspectable execution evidence', 'DC-EXEC-RECEIPT; DC-NODE-ATTEST; DC-BENCH-HARNESS; DE-REPLAY', 'PoC runtime; execution receipts; matched benchmark; verification checks; replay runbook', 'Bounded PoC', 'Milestone', 'New compute modules + reused replay', 'DC-EXEC-RECEIPT; DC-BENCH-HARNESS', 'Representative dataset/workload + comparator', 'Receipt verifies stated fields; benchmark is reproducible', 'No production availability promise', 'Metric contract + observed/derived labels');
INSERT INTO offers (config_id, product_id, tier_id, offer_name, buyer_trigger, outcome, modules_raw, deliverables, typical_format, commercial_model, reusable_core, specific_core, entry_criteria, exit_acceptance, explicit_exclusions, evidence_contract) VALUES ('DC-O4', 2, 4, 'Decentralized Compute Infrastructure Implementation', 'PoC metrics justify production integration', 'Implement distributed execution, verification, monitoring and provider/fallback integration', 'DC-RESOURCE-TOPO; DC-RESOURCE-MARKET; DC-RESILIENCE; SG-PROMOTION-GATE; DE-EVIDENCE-STORE', 'Runtime/integration; scheduler adapters; verification; observability; release gates; handoff', '3–9 months', 'Retainer / milestones', 'Composable platform implementation', 'Provider adapters / performance tuning', 'Accepted PoC + operating ownership', 'Release gate passes on representative workloads', 'No 24/7 ops unless contracted', 'Release evidence + benchmark history');
INSERT INTO offers (config_id, product_id, tier_id, offer_name, buyer_trigger, outcome, modules_raw, deliverables, typical_format, commercial_model, reusable_core, specific_core, entry_criteria, exit_acceptance, explicit_exclusions, evidence_contract) VALUES ('DC-O5', 2, 5, 'Compute Protocol Assurance', 'Existing decentralized compute design needs independent architecture/claim review', 'Check whether trust, execution and performance claims match what the system actually proves', 'SG-THREAT-MODEL; DC-BENCH-HARNESS; DC-NODE-ATTEST; SG-PROMOTION-GATE', 'Claim/evidence ledger; benchmark audit; threat model; failure tests; remediation backlog', 'Project / recurring', 'Retainer / fixed review', 'Reuse assurance + new compute metrics', 'Protocol-specific attack/performance tests', 'Specs/code/benchmark access', 'Claims are classified as supported/bounded/unsupported', 'Not a formal certification', 'Every published numeric claim requires metric contract');
